Hub.IsRoundActive = function(self)
	local rtp = self.Services.Workspace:FindFirstChild("RoundTimerPart");
	if rtp then
		local cr = rtp:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\23\233\76\173\49\242\74\141\59\233\80\187", "\223\84\156\62"), true);
		if (cr and cr:IsA("TextLabel") and (cr.Text ~= "") and (cr.Text ~= "Current Round")) then
			return false;
