		end
		if not hasActiveRole then
			return false;
		end
		return true;
	end
	if self.Services.Workspace:FindFirstChild("GunDrop") then
		return true;
	end
	local coinContainer = self.Services.Workspace:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\245\243\235\211\148\52\216\232\227\212\185\62\196", "\91\182\156\130\189\215"), true);
