Hub.IsPlayerInRound = function(self, player)
	if (not player or not player.Character) then
		return false;
	end
	local root = self:GetRoot(player.Character);
	local hum = player.Character:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\86\102\161\84\112\124\165\81", "\53\30\19\204"));
	if not (root and hum and (hum.Health > 0)) then
		return false;
	end
	if not self:IsRoundActive() then
		return false;
	end
	if (root.Position.Y > 350) then
		return false;
	end
	local data = self:GetPlayerDataMap();
	if (data and (type(data) == "table") and (next(data) ~= nil)) then
		local pd = data[player.Name];
		if not pd then
			return false;
		end
		if (pd.Dead or pd.Killed) then
			return false;
		end
		if (not pd.Role or (pd.Role == "") or (pd.Role == "Lobby") or (pd.Role == "Dead")) then
			return false;
		end
		return true;
	end
	if ((root.Position.Y <= 350) and self:IsRoundActive()) then
		return true;
	end
	return false;
end;
Hub.GetPlayerRole = function(self, player)
	if not self:IsPlayerInRound(player) then
		return "None";
	end
	local char = player.Character;
	local bp = player:FindFirstChildOfClass("Backpack");
	local hasKnife = false;
	if (char and (char:FindFirstChild("Knife") or (char:FindFirstChildWhichIsA("Tool") and char:FindFirstChildWhichIsA("Tool").Name:lower():find("knife")))) then
		hasKnife = true;
	end
	if (bp and (bp:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\210\238\121\130\162", "\199\153\128\16\228")) or (bp:FindFirstChildWhichIsA("Tool") and bp:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\229\37\234\21", "\199\177\74\133\121")).Name:lower():find("knife")))) then
		hasKnife = true;
	end
	local hasGun = false;
	if char then
		for _, item in ipairs(char:GetChildren()) do
			if (item:IsA("Tool") and ((item.Name == "Gun") or item.Name:lower():find(LUAOBFUSACTOR_DECRYPT_STR_0("\191\220\178", "\74\216\169\220\158\87\166")))) then
				hasGun = true;
				break;
			end
		end
	end
	if (not hasGun and bp) then
		for _, item in ipairs(bp:GetChildren()) do
			if (item:IsA("Tool") and ((item.Name == "Gun") or item.Name:lower():find("gun"))) then
				hasGun = true;
				break;
			end
		end
	end
	local data = self:GetPlayerDataMap();
	local pd = data and data[player.Name];
	if (hasKnife or (pd and (pd.Role == "Murderer"))) then
		return LUAOBFUSACTOR_DECRYPT_STR_0("\197\54\1\40\95\250\38\1", "\58\136\67\115\76");
	end
	if hasGun then
		if pd then
			if ((pd.Role == "Hero") or (pd.Hero == true)) then
				return "Hero";
			end
			if (pd.Role == "Innocent") then
				return "Hero";
			end
			if (pd.Role == "Sheriff") then
				if not self.State.OriginalSheriff then
					self.State.OriginalSheriff = player.Name;
				end
				return "Sheriff";
			end
		end
		if (self.State.OriginalSheriff and (self.State.OriginalSheriff ~= player.Name)) then
			return "Hero";
		end
		if not self.State.OriginalSheriff then
			self.State.OriginalSheriff = player.Name;
			return LUAOBFUSACTOR_DECRYPT_STR_0("\194\162\221\75\140\38\173", "\61\145\202\184\57\229\64\203");
		end
		return "Hero";
	end
	if (pd and pd.Role and (pd.Role ~= "") and (pd.Role ~= "Lobby") and (pd.Role ~= "Dead")) then
		if (pd.Role == "Sheriff") then
			if not self.State.OriginalSheriff then
				self.State.OriginalSheriff = player.Name;
			end
			return "Sheriff";
		end
		if ((pd.Role == LUAOBFUSACTOR_DECRYPT_STR_0("\116\87\155\72", "\39\60\50\233")) or (pd.Hero == true)) then
			return "Hero";
		end
		return pd.Role;
	end
	return "Innocent";
end;
