	container.Visible = false;
	container.Parent = screen;
	self.Crosshair.Container = container;
	local dot = Instance.new("Frame");
	dot.Name = "CenterDot";
	dot.AnchorPoint = Vector2.new(0.5, 0.5);
	dot.Position = UDim2.new(0.5, 0, 0.5, 0);
	dot.Size = UDim2.new(0, 3, 0, 3);
	dot.BackgroundColor3 = self.Theme.Accent;
	dot.BorderSizePixel = 0;
	dot.Parent = container;
	self:Corner(dot, 2);
	self:Stroke(dot, Color3.fromRGB(0, 0, 0), 1);
	self.Crosshair.Dot = dot;
	local lines = {};
	local directions = {Top=Vector2.new(0.5, 1),[LUAOBFUSACTOR_DECRYPT_STR_0("\239\73\164\2\79\225", "\60\173\38\208\118\32\140\44")]=Vector2.new(0.5, 0),[LUAOBFUSACTOR_DECRYPT_STR_0("\109\55\231\199", "\175\33\82\129\179\64")]=Vector2.new(1, 0.5),Right=Vector2.new(0, 0.5)};
	for name, anchor in pairs(directions) do
		local line = Instance.new("Frame");
		line.Name = name .. LUAOBFUSACTOR_DECRYPT_STR_0("\194\230\62\202", "\210\142\143\80\175\92");
		line.AnchorPoint = anchor;
		line.BackgroundColor3 = self.Theme.Accent;
		line.BorderSizePixel = 0;
		line.Parent = container;
		self:Corner(line, 2);
		self:Stroke(line, Color3.fromRGB(0, 0, 0), 1);
		lines[name] = line;
	end
	self.Crosshair.Lines = lines;
	self:UpdateCrosshairGeometry();
	if self.Crosshair.Connection then
		self.Crosshair.Connection:Disconnect();
