	self:SetFarmNoClip(false);
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\150\229\22\0\89\127\54\186", "\95\222\144\123\97\55\16"));
	if root then
