		local coinBags = mg:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\62\133\183\70", "\131\121\228\218\35")) and mg.Game:FindFirstChild("CoinBags");
		if not coinBags then
			return;
