	local decPart = absN - intPart;
	local formatted = tostring(intPart);
	local k;
	while true do
		formatted, k = formatted:gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\107\29\72\227\240\120\30\28\77\249\177\57\81\16\1\245", "\28\53\53\101\220\213"), LUAOBFUSACTOR_DECRYPT_STR_0("\72\13\68\4\8", "\191\109\60\104\33\58\193\48"));
		if (k == 0) then
			break;
		end
	end
	if (decPart >= 0.01) then
		local decStr = string.format(LUAOBFUSACTOR_DECRYPT_STR_0("\194\153\74\225", "\135\231\183\120"), decPart):sub(2);
		decStr = decStr:gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\182\65\8", "\201\134\106\44\132\85\122"), "");
		if (decStr ~= ".") then
			return sign .. formatted .. decStr;
		end
	end
	return sign .. formatted;
end;
