	end
	if tLabel then
		tLabel.Text = "Them: " .. self:FormatNumber(theirVal) .. " Val";
	end
	if vLabel then
		local diff = theirVal - yourVal;
		if ((yourVal == 0) and (theirVal == 0)) then
			vLabel.Text = "Add items to calculate";
			vLabel.TextColor3 = self.Theme.TextDim;
		elseif (diff > 0) then
			vLabel.Text = LUAOBFUSACTOR_DECRYPT_STR_0("\30\221\168\252\123\98", "\83\73\148\230\220") .. self:FormatNumber(diff) .. ")";
			vLabel.TextColor3 = Color3.fromRGB(50, 230, 100);
