	if (grip and (#grip >= 12)) then
		pcall(function()
			tool.Grip = CFrame.new(table.unpack(grip));
		end);
	end
	local sounds = self:ApplySkinFX(rec, tool, body, handle);
	if next(sounds) then
		for _, inst in ipairs(tool:GetDescendants()) do
			if (inst:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\227\39\76\124\234", "\142\176\72\57\18")) and not sounds[inst.Name]) then
				self:BackupSkinProp(inst, {[LUAOBFUSACTOR_DECRYPT_STR_0("\176\62\28\49\171\52", "\68\198\81\112")]=inst.Volume});
