		if (readfile and (not isfile or isfile(LUAOBFUSACTOR_DECRYPT_STR_0("\57\231\131\197\212\94\89\216\37\226", "\171\74\140\234\171\167\112\51")))) then
			return readfile("skins.json");
		end
	end);
	if (okFile and (type(localContent) == "string") and (#localContent > 1000)) then
		content = localContent;
	end
	if not content then
		local url = self.SkinSystem.DatabaseURL;
		if (url and (url ~= "")) then
			local okNet, res = pcall(function()
				if game.HttpGet then
					return game:HttpGet(url);
				end
			end);
			if (okNet and (type(res) == LUAOBFUSACTOR_DECRYPT_STR_0("\60\26\94\86\255\170", "\205\79\110\44\63\145")) and (#res > 1000)) then
				content = res;
			end
		end
	end
	if content then
		local okParse, data = pcall(self.Services.HttpService.JSONDecode, self.Services.HttpService, content);
		if (okParse and (type(data) == "table")) then
			self:ProcessSkinDatabase(data);
			return true;
		end
	end
	return false;
end;
