			targetPart = pad:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\42\33\81", "\180\122\64\53\233\93\75")) or pad.PrimaryPart or pad:FindFirstChildWhichIsA("BasePart");
		end
