			if (ch:IsA("TextButton") or ch:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\5\107\171\76\210", "\64\67\25\202\33\183")) or ch:IsA("TextLabel")) then
				ch:Destroy();
			end
		end
		if (q == "") then
			searchDropdown.Visible = false;
			for _, tabFrame in pairs(self.State.Tabs) do
				for _, obj in ipairs(tabFrame:GetDescendants()) do
					if (obj:IsA("Frame") and obj.Name:find("^Card_")) then
						obj.Visible = true;
					end
				end
			end
			return;
		end
		local matches = {};
		local tabOrder = {"Combat","Visuals",LUAOBFUSACTOR_DECRYPT_STR_0("\196\231\98\191", "\35\137\142\17\220\78\178"),"Maps","Animation","Config"};
