			table.insert(matches, 1, {Tab=LUAOBFUSACTOR_DECRYPT_STR_0("\233\214\19\176\222\211\19", "\197\191\191\96"),Title="3D Avatar Preview (Сбоку)",Sub="Открыть 3D панель аватара справа",IsSidePreview=true});
		end
		for _, tabName in ipairs(tabOrder) do
			local tabFrame = self.State.Tabs[tabName];
			if tabFrame then
				for _, obj in ipairs(tabFrame:GetDescendants()) do
					if (obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\236\59\236\67\93", "\45\170\73\141\46\56\136")) and obj.Name:find(LUAOBFUSACTOR_DECRYPT_STR_0("\191\44\204\247\171\184", "\103\225\111\173\133\207\231"))) then
						local cardHeader = obj:FindFirstChild("CardHeader");
						local titleObj = cardHeader and cardHeader:FindFirstChild("CardTitle");
						local cardTitle = (titleObj and titleObj:IsA("TextLabel") and titleObj.Text) or obj.Name:gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\114\167\244\71\72\187", "\53\44\228\149"), "");
						local matched = false;
						local matchedSub = nil;
						local tabAliases = {[LUAOBFUSACTOR_DECRYPT_STR_0("\238\212\54\7\202\48", "\68\173\187\91\101\171")]="комбат бой убийца шериф стрельба silent aim",Visuals="визуал визуалы есп прицел мир esp crosshair",Misc="миск скорость прыжок supreme values noclip speed",[LUAOBFUSACTOR_DECRYPT_STR_0("\209\14\2\212", "\185\156\111\114\167\41\226\29")]="карты мапы голоса выбор vote",Animation="анимации эмоции catalog emotes",Config="конфиг настройки выгрузка меню binds"};
						local aliasText = tabAliases[tabName] or "";
						if (tabName:lower():find(q, 1, true) or aliasText:find(q, 1, true)) then
							matched = true;
						elseif cardTitle:lower():find(q, 1, true) then
							matched = true;
						else
							for _, desc in ipairs(obj:GetDescendants()) do
								if (desc:IsA("TextLabel") and (desc ~= titleObj) and desc.Text:lower():find(q, 1, true)) then
									matched = true;
									matchedSub = desc.Text;
									break;
								end
							end
						end
						if matched then
							table.insert(matches, {Tab=tabName,[LUAOBFUSACTOR_DECRYPT_STR_0("\40\4\4\36", "\131\107\101\118\64\212")]=obj,Title=cardTitle,Sub=matchedSub});
						end
						if (tabName == self.Config.ActiveTab) then
							obj.Visible = matched;
