Hub.ResolveAnimationId = function(self, assetId)
	local rawId = tostring(assetId);
	local ok, objs = pcall(game.GetObjects, game, LUAOBFUSACTOR_DECRYPT_STR_0("\191\55\85\95\190\38\72\74\164\49\23\17\226", "\62\205\85\45") .. rawId);
	if (ok and objs and (#objs > 0)) then
		for _, obj in ipairs(objs) do
			if (obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\84\2\168\164\3\157\0\122\2", "\105\21\108\193\201\98\233")) and (obj.AnimationId ~= "")) then
				return obj.AnimationId;
			end
			local found = obj:FindFirstChildWhichIsA("Animation", true);
			if (found and (found.AnimationId ~= "")) then
				return found.AnimationId;
			end
		end
	end
	return "rbxassetid://" .. rawId;
end;
